const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;padding:6px;color:var(--ink);background:transparent;font:12px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;overflow:hidden}\n.card *{box-sizing:border-box}\n.shell{display:flex;flex-direction:column;height:100%;min-height:0;min-width:0;gap:4px}\n.hd{display:flex;align-items:center;gap:4px;min-height:24px;flex:none}\n.ttl{flex:1;min-width:0;font-size:13px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.bd{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;overflow:hidden}\n.tabs{display:flex;gap:2px;flex:none;padding-top:3px;border-top:1px solid var(--line)}\n.tab{flex:1;min-width:0;min-height:24px;padding:2px 0;border:0;border-radius:6px;background:transparent;color:var(--muted);font:inherit;font-size:12px;cursor:pointer}\n.tab.on{background:var(--soft);color:var(--ink);font-weight:700;box-shadow:inset 0 -2px 0 var(--accent)}\n.btn{min-height:26px;padding:3px 9px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);font:inherit;font-size:12px;white-space:nowrap;cursor:pointer}\n.btn:disabled,.sg:disabled,.chip:disabled{opacity:.5;cursor:default}\n.btn.primary{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:700}\n.btn.sec{border-color:var(--accent)}\n.btn.ghost{background:transparent}\n.btn.danger{border-color:var(--accent-alt);font-weight:700}\n.btn.back{padding:2px 8px;font-size:15px;line-height:1}\n.btn.sq{padding:3px 6px}\n.inp{width:100%;min-width:0;padding:4px 6px;border:1px solid var(--line);border-radius:7px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:12px}\n.inp:focus-visible,.btn:focus-visible,.tab:focus-visible,.chip:focus-visible,.sg:focus-visible,.pname:focus-visible,.prog:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.ta{resize:none;min-height:54px}\n.err{padding:3px 6px;border:1px solid var(--accent-alt);border-radius:7px;font-size:11px;background:var(--soft)}\n.hint,.sm,.note,.lh,.rng,.lab{color:var(--muted);font-size:11px}\n.sm{overflow-wrap:anywhere}\n.empty{padding:10px 4px;color:var(--muted);font-size:12px}\n.row{display:flex;gap:6px;align-items:center;flex:none}\n.row.wrap{flex-wrap:wrap}\n.vw{flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.form{flex:1;min-height:0;display:flex;flex-direction:column;gap:6px}\n.formbody{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.fld{display:flex;flex-direction:column;gap:2px}\n.home{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:6px;overflow:auto}\n.left{display:flex;flex-direction:column;gap:5px;min-width:0}\n.right{display:flex;flex-direction:column;flex:1;min-height:0;min-width:0;gap:3px}\n.seg{display:flex;flex:none;border:1px solid var(--line);border-radius:8px;overflow:hidden}\n.sg{flex:1;min-width:0;min-height:24px;padding:2px 0;border:0;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:12px;cursor:pointer}\n.sg+.sg{border-left:1px solid var(--line)}\n.sg.on{background:var(--accent);color:var(--on-accent);font-weight:700}\n.dates{display:flex;align-items:center;gap:4px}\n.dates .inp{flex:1;padding:3px 4px;font-size:11px}\n.meta{display:flex;align-items:center;justify-content:space-between;gap:6px}\n.meta .btn{min-height:22px;padding:1px 7px;font-size:11px}\n.rng{font-weight:600;color:var(--ink);white-space:nowrap}\n.chips{display:flex;flex-wrap:wrap;gap:4px;max-height:84px;overflow:auto}\n.chip{max-width:100%;padding:2px 8px;border:1px solid var(--line);border-radius:999px;background:var(--panel-paper);color:var(--ink);font:inherit;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;cursor:pointer}\n.chip.on{background:var(--soft);border-color:var(--accent);font-weight:700}\n.prog{display:flex;flex-direction:column;gap:3px;padding:0;border:0;background:transparent;color:inherit;font:inherit;text-align:left;cursor:pointer}\n.bar{display:flex;gap:2px;height:6px}\n.bar i{flex:1;border-radius:3px;background:var(--line)}\n.bar i.b-done,.bar i.b-skipped{background:var(--accent)}\n.bar i.b-running{background:var(--accent-alt)}\n.bar i.b-unavailable,.bar i.b-error,.bar i.b-stale{background:transparent;box-shadow:inset 0 0 0 1px var(--accent-alt)}\n.pl{font-size:11px;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.acts{display:flex;gap:6px;flex:none}\n.acts .run{flex:1;min-height:30px}\n.latest{display:none;align-items:center;justify-content:space-between;gap:8px;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--soft)}\n.steps,.cfgs,.plist,.ents,.hist{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:3px}\n.right .steps{flex:1;min-height:0;overflow:auto}\n.step{display:flex;gap:6px;align-items:flex-start;padding:4px 6px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper)}\n.step.s-running{border-color:var(--accent-alt);box-shadow:inset 3px 0 0 var(--accent-alt)}\n.step.s-done{box-shadow:inset 3px 0 0 var(--accent)}\n.step.s-unavailable,.step.s-error,.step.s-stale{border-style:dashed;border-color:var(--accent-alt)}\n.ic{flex:none;width:16px;height:16px;border-radius:50%;background:var(--soft);text-align:center;font-size:11px;line-height:16px;font-weight:700}\n.sb{flex:1;min-width:0}\n.sn{font-weight:600;overflow-wrap:anywhere}\n.cfg,.prow,.ent{display:flex;gap:6px;align-items:center;padding:4px 6px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper)}\n.cfg.off .sn{color:var(--muted);text-decoration:line-through}\n.cfg input[type=checkbox],.prow input[type=checkbox]{flex:none;width:16px;height:16px;accent-color:var(--accent)}\n.mv{display:flex;gap:3px;flex:none}\n.mv .btn{min-height:24px;padding:2px 6px;font-size:11px}\n.pname{flex:1;min-width:0;display:flex;flex-direction:column;gap:1px;padding:3px 4px;border:0;background:transparent;color:inherit;font:inherit;text-align:left;cursor:pointer}\n.hist .pname{border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);padding:5px 8px;width:100%}\n.pn{font-weight:600;overflow-wrap:anywhere}\n.ent{flex-direction:column;align-items:stretch;gap:2px}\n.eh{display:flex;align-items:center;gap:6px}\n.eh .btn{margin-left:auto;min-height:22px;padding:1px 7px;font-size:11px}\n.et{overflow-wrap:anywhere;white-space:pre-wrap}\n.tag{padding:0 6px;border:1px solid var(--accent);border-radius:999px;font-size:11px}\n.tag.t-issue{border-style:dashed;border-color:var(--accent-alt)}\n.rpt{flex:1;min-height:0;display:flex;flex-direction:column;gap:4px}\n.rmeta{font-size:11px;font-weight:600}\n.rta{flex:1;min-height:40px;resize:none;line-height:1.5;white-space:pre-wrap}\n.cpmsg{align-self:center}\n\n/* 3x3\uff1a\u5355\u5217\uff0c\u53ea\u663e\u793a\u8fdb\u5ea6\u6761\u4e0e\u8fd0\u884c\u6309\u94ae\uff0c\u6b65\u9aa4\u8be6\u60c5\u70b9\u8fdb\u5ea6\u6761\u67e5\u770b */\n.card[data-size=\"3x3\"] .right,\n.card[data-size=\"3x3\"] .chips{display:none}\n.card[data-size=\"3x3\"] .note{display:none}\n.card[data-size=\"3x3\"] .hd{min-height:22px}\n.card[data-size=\"3x3\"] .ttl{font-size:12px}\n.card[data-size=\"3x3\"] .home{gap:5px}\n/* 6x3\uff1a\u5de6\u63a7\u5236\u3001\u53f3\u6b65\u9aa4 */\n.card[data-size=\"6x3\"] .chips,\n.card[data-size=\"6x3\"] .prog{display:none}\n.card[data-size=\"6x3\"] .home{display:grid;grid-template-columns:minmax(150px,176px) minmax(0,1fr);gap:8px;overflow:hidden}\n.card[data-size=\"6x3\"] .left{overflow:auto;min-height:0}\n.card[data-size=\"6x3\"] .note{font-size:10px}\n/* 3x6\uff1a\u5355\u5217\uff0c\u9879\u76ee\u82af\u7247 + \u6b65\u9aa4\u5217\u8868 */\n.card[data-size=\"3x6\"] .sum,\n.card[data-size=\"3x6\"] .prog{display:none}\n.card[data-size=\"3x6\"] .meta{justify-content:flex-start}\n.card[data-size=\"3x6\"] .home{overflow:hidden}\n.card[data-size=\"3x6\"] .left{flex:none}\n/* 6x6\uff1a\u53cc\u5217\uff0c\u5e95\u90e8\u5c55\u793a\u6700\u8fd1\u4e00\u4efd\u5468\u62a5 */\n.card[data-size=\"6x6\"] .sum,\n.card[data-size=\"6x6\"] .prog{display:none}\n.card[data-size=\"6x6\"] .meta{justify-content:flex-start}\n.card[data-size=\"6x6\"] .chips{max-height:150px}\n.card[data-size=\"6x6\"] .home{display:grid;grid-template-columns:minmax(170px,210px) minmax(0,1fr);grid-template-rows:minmax(0,1fr) auto;gap:8px 12px;overflow:hidden}\n.card[data-size=\"6x6\"] .left{overflow:auto;min-height:0}\n.card[data-size=\"6x6\"] .latest{display:flex;grid-column:1 / -1}\n.card[data-size=\"6x6\"] .tab,.card[data-size=\"6x6\"] .btn{font-size:13px}\n/* \u7a84\u5361\u7247\uff1a\u7f16\u8f91\u884c\u6362\u884c\uff0c\u907f\u514d\u6324\u788e\u6587\u5b57 */\n.card[data-size=\"3x3\"] .cfg,.card[data-size=\"3x6\"] .cfg{flex-wrap:wrap}\n.card[data-size=\"3x3\"] .cfg .sb,.card[data-size=\"3x6\"] .cfg .sb{flex-basis:calc(100% - 28px)}\n.card[data-size=\"3x3\"] .mv,.card[data-size=\"3x6\"] .mv{margin-left:22px}\n";
function kindList(){return [['calendar','读取日历'],['mail','读取邮件'],['projects','整理项目进展与问题'],['draft','撰写周报草稿']];}
function kindName(k){const f=kindList().find(x=>x[0]===k);return f?f[1]:k;}
function kindTag(k){return {calendar:'平台暂无日历接口，只保存设置',mail:'需先在平台绑定邮箱',projects:'使用本卡片内的项目记录',draft:'按记录拼出草稿，不含 AI 改写'}[k]||'';}
function stLabel(s){return {pending:'待执行',running:'进行中',done:'完成',unavailable:'未接入',error:'失败',skipped:'已跳过',stale:'已中断'}[s]||s;}
function stIcon(s){return {pending:'○',running:'◐',done:'✓',unavailable:'!',error:'✕',skipped:'–',stale:'✕'}[s]||'○';}
function pad(n){return n<10?'0'+n:String(n);}
function fmtDate(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate());}
function parseDate(s){const p=String(s||'').split('-').map(Number);return new Date(p[0],p[1]-1,p[2]);}
function addDays(s,n){const d=parseDate(s);d.setDate(d.getDate()+n);return fmtDate(d);}
function weekStart(s){const d=parseDate(s);d.setDate(d.getDate()-((d.getDay()+6)%7));return fmtDate(d);}
function shortDate(s){return String(s||'').slice(5).replace('-','/');}
function timeStr(ms){const d=new Date(ms);return pad(d.getMonth()+1)+'/'+pad(d.getDate())+' '+pad(d.getHours())+':'+pad(d.getMinutes());}
function inRange(d,r){return !!r&&!!d&&d>=r.start&&d<=r.end;}
function resolveRange(set,today){
  if(set.mode==='custom'){
    if(!set.start||!set.end||set.start>set.end)return null;
    return {start:set.start,end:set.end};
  }
  const ws=weekStart(today);
  if(set.mode==='last')return {start:addDays(ws,-7),end:addDays(ws,-1)};
  return {start:ws,end:addDays(ws,6)};
}
function norm(s){
  s=s||{};
  const st=Object.assign({mode:'this',start:'',end:'',requirements:'',selected:[],steps:[]},s.settings||{});
  return Object.assign({},s,{settings:st,projects:s.projects||[],runs:s.runs||[]});
}
function initialize(s){
  s=s||{};
  if(s.settings&&Array.isArray(s.settings.steps))return s;
  const n=norm(s);
  n.settings=Object.assign({},n.settings,{steps:[
    {id:'step-calendar',kind:'calendar',title:'查看日历',note:'',enabled:true},
    {id:'step-mail',kind:'mail',title:'查看邮件',note:'',enabled:true},
    {id:'step-projects',kind:'projects',title:'整理项目进展和问题',note:'',enabled:true},
    {id:'step-draft',kind:'draft',title:'撰写周报',note:'',enabled:true}
  ]});
  return n;
}
function projEntries(p,range){
  return (p.entries||[]).filter(e=>inRange(e.date,range)).sort((a,b)=>a.date<b.date?-1:(a.date>b.date?1:0));
}
function fromStr(x){
  if(x&&typeof x==='object')return String(x.name||x.address||x.email||'');
  return String(x||'');
}
function mailItems(data){
  const arr=Array.isArray(data)?data:(data&&(Array.isArray(data.messages)?data.messages:(Array.isArray(data.items)?data.items:(Array.isArray(data.list)?data.list:null))));
  if(!arr)return null;
  return arr.map(m=>({
    subject:String((m&&(m.subject||m.title))||'(无主题)'),
    from:fromStr(m&&(m.from||m.sender)),
    date:String((m&&(m.date||m.received_at||m.time))||'').slice(0,10)
  }));
}
function buildReport(range,projs,acc){
  const L=[];
  L.push('周报 '+shortDate(range.start)+' – '+shortDate(range.end));
  L.push('');
  const section=(title,type,emptyText)=>{
    L.push(title);
    if(!acc.proj){L.push('（本次未执行「整理项目」步骤）');return;}
    if(!projs.length){L.push('（未选择项目）');return;}
    projs.forEach(p=>{
      L.push('【'+p.name+'】');
      const list=p.entries.filter(e=>(e.type==='issue')===(type==='issue'));
      if(!list.length)L.push('- '+emptyText);
      list.forEach(e=>L.push('- '+shortDate(e.date)+' '+e.text));
    });
  };
  section('一、项目进展','progress','本期无进展记录');
  L.push('');
  section('二、问题与风险','issue','本期无问题记录');
  L.push('');
  L.push('三、日程');
  L.push(acc.ran.calendar?'（未读取日历：平台暂无日历接口，请手动补充）':'（未启用「读取日历」步骤）');
  L.push('');
  L.push('四、邮件');
  if(!acc.ran.mail)L.push('（未启用「读取邮件」步骤）');
  else if(!acc.mail)L.push('（未读取邮件：'+(acc.mailNote||'未获取')+'）');
  else if(!acc.mail.length)L.push('（范围内没有邮件）');
  else acc.mail.forEach(m=>L.push('- '+(m.date?shortDate(m.date)+' ':'')+(m.from?m.from+'：':'')+m.subject));
  return L.join('\n');
}

function mount(ctx){
  const {root,el,state,ui,update,redraw,uid,day,host,size}=ctx;
  const S=norm(state);
  const st=S.settings;
  const sel=st.selected;
  const range=resolveRange(st,day());
  if(!ui.view)ui.view='home';
  if(!ui.draft)ui.draft={};
  if(!ui.rtext)ui.rtext={};
  const kids=(a)=>a.filter(Boolean);
  const btn=(label,onclick,cls,dis)=>el('button',{type:'button',class:'btn '+(cls||''),onclick:onclick,disabled:!!dis},label);
  const go=(view,extra)=>{
    ui.view=view;ui.err='';ui.confirm='';ui.back=null;
    if(extra)Object.assign(ui,extra);
    redraw();
  };
  const save=async(fn,after)=>{
    try{
      ui.err='';
      await update(s=>fn(norm(s)));
      if(after)after();
      redraw();
    }catch(e){
      ui.err='保存失败：'+(e&&e.message?e.message:'未知错误');
      redraw();
    }
  };
  const setSettings=(patch,after)=>save(s=>{s.settings=Object.assign({},s.settings,patch);return s;},after);
  const danger=(key,label,act)=>ui.confirm===key
    ?btn('确认'+label,act,'danger')
    :btn(label,()=>{ui.confirm=key;redraw();},'ghost');
  const errLine=()=>ui.err?el('div',{class:'err',role:'alert'},'⚠ '+ui.err):null;

  function form(fields,onSave,more){
    const d=ui.draft;
    const rows=fields.map(f=>{
      let inp;
      if(f.type==='select'){
        inp=el('select',{class:'inp',onchange:e=>{d[f.key]=e.target.value;}},...f.options.map(o=>el('option',{value:o[0]},o[1])));
        inp.value=d[f.key]||f.options[0][0];
      }else if(f.type==='textarea'){
        inp=el('textarea',{class:'inp ta',rows:f.rows||3,placeholder:f.ph||'',oninput:e=>{d[f.key]=e.target.value;}});
        inp.value=d[f.key]||'';
      }else{
        const h=e=>{d[f.key]=e.target.value;};
        inp=el('input',{class:'inp',type:f.type||'text',placeholder:f.ph||'',oninput:h,onchange:h});
        inp.value=d[f.key]||'';
      }
      return el('label',{class:'fld'},el('span',{class:'lab'},f.label),inp);
    });
    return el('div',{class:'form'},
      el('div',{class:'formbody'},...kids(rows.concat([errLine()]))),
      el('div',{class:'row'},...kids([btn('保存',()=>onSave(d),'primary')].concat(more||[],[btn('取消',()=>go(ui.back||PARENT[ui.view]||'home'))]))));
  }

  const PARENT={stepForm:'steps',projForm:'projects',entryForm:'project',project:'projects',run:'home',report:'history'};
  const TABS=[['home','运行'],['steps','设置'],['projects','项目'],['history','周报']];
  const TAB_OF={home:'home',run:'home',steps:'steps',stepForm:'steps',projects:'projects',project:'projects',projForm:'projects',entryForm:'projects',history:'history',report:'history'};
  const TITLE={home:'周报流程',run:'运行进度',steps:'步骤与要求',stepForm:ui.editId?'编辑步骤':'添加步骤',projects:'项目',project:'项目记录',projForm:ui.editProj?'项目名称':'添加项目',entryForm:'添加记录',history:'周报',report:'周报草稿'};

  function render(){
    const v=ui.view;
    const views={home:vHome,run:vRun,steps:vSteps,stepForm:vStepForm,projects:vProjects,project:vProject,projForm:vProjForm,entryForm:vEntryForm,history:vHistory,report:vReport};
    let title=TITLE[v]||'周报流程';
    if(v==='project'){const p=S.projects.find(x=>x.id===ui.pid);if(p)title=p.name;}
    const sub=!!PARENT[v];
    root.append(el('div',{class:'shell v-'+v},
      el('div',{class:'hd'},...kids([
        sub?btn('‹',()=>go(ui.back||PARENT[v]),'ghost back'):null,
        el('div',{class:'ttl'},title)])),
      el('div',{class:'bd'},(views[v]||vHome)()),
      el('div',{class:'tabs',role:'tablist'},...TABS.map(t=>el('button',{type:'button',role:'tab',class:'tab'+(TAB_OF[v]===t[0]?' on':''),'aria-selected':String(TAB_OF[v]===t[0]),onclick:()=>go(t[0])},t[1])))));
  }


  const latestRun=()=>S.runs[0]||null;
  const runStatus=(r)=>r.status==='running'&&!ui.running?'stale':r.status;
  const runLabel=(r)=>({running:'进行中',partial:'部分完成（有步骤未接入或失败）',done:'全部完成',stale:'已中断'}[runStatus(r)]||r.status);
  const stepRow=(s,full)=>el('li',{class:'step s-'+s.status},
    el('span',{class:'ic','aria-hidden':'true'},stIcon(s.status)),
    el('div',{class:'sb'},el('div',{class:'sn'},s.title),
      el('div',{class:'sm'},stLabel(s.status)+(s.msg?' · '+s.msg:''))));

  function toggleSel(id){
    setSettings({selected:sel.includes(id)?sel.filter(x=>x!==id):sel.concat([id])});
  }

  function vHome(){
    const run=latestRun();
    const enabled=st.steps.filter(x=>x.enabled);
    const running=!!ui.running;
    const steps=run?run.steps.map(s=>Object.assign({},s,{status:(run.status==='running'&&!running&&s.status==='running')?'stale':s.status})):enabled.map(x=>({id:x.id,kind:x.kind,title:x.title,status:'pending',msg:''}));
    const canRun=!running&&!!range&&enabled.length>0;
    const total=steps.length;
    const doneN=steps.filter(s=>s.status==='done'||s.status==='skipped').length;
    const curIdx=steps.findIndex(s=>s.status==='running');
    let prog='尚未运行';
    if(run){
      if(curIdx>=0)prog='第 '+(curIdx+1)+'/'+total+' 步 · '+steps[curIdx].title;
