    }
    const seg=el('div',{class:'seg',role:'group','aria-label':'日期范围'},...[['this','本周'],['last','上周'],['custom','自定义']].map(m=>
      el('button',{type:'button',class:'sg'+(st.mode===m[0]?' on':''),'aria-pressed':String(st.mode===m[0]),disabled:running,onclick:()=>setSettings({mode:m[0]})},m[1])));
