    const latest=run&&run.report?el('div',{class:'latest'},
      el('span',{},'周报草稿 '+shortDate(run.range.start)+'–'+shortDate(run.range.end)+' · '+(run.report.reviewed?'已审阅':'待审阅')+' · 未发送'),
      btn('打开',()=>go('report',{rid:run.id,back:'home'}),'sec')):null;
