  const patchRun=(id,fn)=>update(s=>{const m=norm(s);m.runs=m.runs.map(r=>r.id===id?fn(r):r);return m;});
  const patchStep=(id,i,p,extra)=>patchRun(id,r=>Object.assign({},r,extra||{},{steps:r.steps.map((x,j)=>j===i?Object.assign({},x,p,{at:Date.now()}):x)}));

  async function execStep(kind,rg,projs,acc){
    acc.ran[kind]=true;
    if(kind==='calendar')return {status:'unavailable',msg:'平台暂无日历读取接口，未读取；步骤已保留。'};
    if(kind==='mail'){
      try{
        const r=await host.fetchData('connected.mail.message-list');
        if(!r||r.status!=='ok'||!r.data)throw new Error((r&&(r.errorCode||r.status))||'无数据');
        const all=mailItems(r.data);
        if(!all)throw new Error('返回格式无法识别');
        acc.mail=all.filter(m=>!m.date||inRange(m.date,rg));
        return {status:'done',msg:'范围内 '+acc.mail.length+' 封（仅标题等元数据）'};
      }catch(e){
        const t=String((e&&e.message)||e);
        if(/permission_denied/.test(t)){
          acc.mailNote='邮箱未连接';
          return {status:'unavailable',msg:'邮箱未连接：请先在平台连接邮箱后再运行。'};
        }
        acc.mailNote='读取失败';
        return {status:'error',msg:'读取失败：'+t.slice(0,60)};
      }
    }
    if(kind==='projects'){
      acc.proj=true;
      if(!projs.length)return {status:'skipped',msg:'未选择项目'};
      let a=0,b=0;
      projs.forEach(p=>p.entries.forEach(e=>{if(e.type==='issue')b++;else a++;}));
      return {status:'done',msg:projs.length+' 个项目 · 进展 '+a+' 条 · 问题 '+b+' 条'};
    }
    if(kind==='draft'){
      acc.report=buildReport(rg,projs,acc);
      return {status:'done',msg:'已按记录拼出草稿，未经 AI 改写；不会自动发送'};
    }
    return {status:'skipped',msg:'未知步骤类型'};
  }

  async function runFlow(){
    if(ui.running)return;
    const rg=resolveRange(st,day());
    const enabled=st.steps.filter(x=>x.enabled);
    if(!rg||!enabled.length){ui.err=!rg?'请先设置有效的日期范围':'没有启用的步骤';redraw();return;}
    const picked=S.projects.filter(p=>sel.includes(p.id));
    const projs=picked.map(p=>({id:p.id,name:p.name,entries:projEntries(p,rg)}));
    const run={id:uid(),at:Date.now(),range:rg,projectIds:picked.map(p=>p.id),status:'running',report:null,
      steps:enabled.map(x=>({id:x.id,kind:x.kind,title:x.title,status:'pending',msg:''}))};
    const acc={ran:{},proj:false,mail:null,mailNote:'',report:null};
    const results=[];
    ui.running=true;ui.err='';ui.rid=run.id;
    try{
      await update(s=>{const m=norm(s);m.runs=[run].concat(m.runs).slice(0,10);return m;});
      for(let i=0;i<run.steps.length;i++){
        await patchStep(run.id,i,{status:'running'});
        let r;
        try{r=await execStep(run.steps[i].kind,rg,projs,acc);}
        catch(e){r={status:'error',msg:'执行出错：'+String((e&&e.message)||e).slice(0,60)};}
        results.push(r);
        const extra=(run.steps[i].kind==='draft'&&acc.report)?{report:{text:acc.report,at:Date.now(),reviewed:false,edited:false}}:null;
        await patchStep(run.id,i,r,extra);
      }
      const bad=results.some(r=>r.status==='error'||r.status==='unavailable');
      await patchRun(run.id,r=>Object.assign({},r,{status:bad?'partial':'done',finishedAt:Date.now()}));
      ui.running=false;
      if(acc.report&&ui.view==='home'){ui.view='report';ui.rid=run.id;ui.back='home';}
      redraw();
    }catch(e){
      ui.running=false;
      ui.err='运行中断：'+String((e&&e.message)||e).slice(0,80);
      redraw();
    }
  }

  function mutateStep(id,patch){
    save(s=>{s.settings=Object.assign({},s.settings,{steps:s.settings.steps.map(x=>x.id===id?Object.assign({},x,patch):x)});return s;});
  }
  function moveStep(id,dir){
    save(s=>{
      const a=s.settings.steps.slice();
      const i=a.findIndex(x=>x.id===id),j=i+dir;
      if(i<0||j<0||j>=a.length)return s;
      const t=a[i];a[i]=a[j];a[j]=t;
      s.settings=Object.assign({},s.settings,{steps:a});
      return s;
    });
  }

