          el('span',{class:'pn'},p.name),
          el('span',{class:'sm'},'本期 进展 '+a+' · 问题 '+b+(on?' · 已纳入':' · 未纳入'))));
    });
    return el('div',{class:'vw'},
      el('div',{class:'row'},btn('＋ 添加项目',()=>go('projForm',{editProj:null,draft:{name:''}}),'sec')),
      rows.length?el('ul',{class:'plist'},...rows):el('div',{class:'empty'},'还没有项目。添加项目后，可在其下记录进展与问题，运行时按日期范围汇总。'),
      errLine());
  }

  function vProject(){
    const p=S.projects.find(x=>x.id===ui.pid);
    if(!p)return el('div',{class:'vw empty'},'项目不存在。');
