        el('span',{class:'sm'},shortDate(e.date)+(inRange(e.date,range)?' · 本期':'')),
        danger('del-e'+e.id,'删除',()=>save(s=>{s.projects=s.projects.map(q=>q.id===p.id?Object.assign({},q,{entries:(q.entries||[]).filter(x=>x.id!==e.id)}):q);return s;},()=>{ui.confirm='';}))),
      el('div',{class:'et'},e.text)));
    return el('div',{class:'vw'},
      el('div',{class:'row'},
        btn('＋ 记录',()=>go('entryForm',{pid:p.id,back:'project',draft:{type:'progress',date:day(),text:''}}),'sec'),
        btn('改名/删除',()=>go('projForm',{editProj:p.id,back:'project',draft:{name:p.name}}),'ghost')),
      items.length?el('ul',{class:'ents'},...items):el('div',{class:'empty'},'还没有记录。点「＋ 记录」添加本周进展或遇到的问题。'),
