  function vEntryForm(){
    const pid=ui.pid;
    return form([
      {key:'type',label:'类型',type:'select',options:[['progress','进展'],['issue','问题']]},
      {key:'date',label:'日期',type:'date'},
      {key:'text',label:'内容',type:'textarea',rows:4,ph:'一两句话即可'}],(d)=>{
      const text=(d.text||'').trim();
