      const nid=uid();
      save(s=>{
        s.projects=s.projects.map(p=>p.id===pid?Object.assign({},p,{entries:(p.entries||[]).concat([{id:nid,type:d.type==='issue'?'issue':'progress',date:d.date,text:text}])}):p);
        return s;
      },()=>{ui.view='project';ui.back=null;});
    });
