  function vHistory(){
    if(!S.runs.length)return el('div',{class:'vw empty'},'还没有周报。到「运行」页点运行，草稿会保存在这里供你审阅。');
    return el('div',{class:'vw'},el('ul',{class:'hist'},...S.runs.map(r=>el('li',{},
      el('button',{type:'button',class:'pname',onclick:()=>r.report?go('report',{rid:r.id,back:'history'}):go('run',{rid:r.id,back:'history'})},
        el('span',{class:'pn'},shortDate(r.range.start)+' – '+shortDate(r.range.end)+' · '+timeStr(r.at)),
        el('span',{class:'sm'},(r.report?(r.report.reviewed?'已审阅':'待审阅')+' · 未发送':'无周报草稿')+' · '+runLabel(r)))))));
  }

  function vReport(){
    const run=S.runs.find(r=>r.id===ui.rid)||S.runs.find(r=>r.report);
    if(!run||!run.report)return el('div',{class:'vw empty'},'还没有可审阅的周报草稿。');
    const rid=run.id;
    const ta=el('textarea',{class:'inp rta','aria-label':'周报草稿，可直接修改',oninput:e=>{ui.rtext[rid]=e.target.value;}});
    ta.value=ui.rtext[rid]!==undefined?ui.rtext[rid]:run.report.text;
    const msg=el('span',{class:'sm cpmsg',role:'status'},'');
    const cur=()=>ui.rtext[rid]!==undefined?ui.rtext[rid]:run.report.text;
    const saveRep=(reviewed)=>save(s=>{
      s.runs=s.runs.map(r=>r.id===rid?Object.assign({},r,{report:Object.assign({},r.report,{text:cur(),reviewed:reviewed,edited:r.report.edited||cur()!==r.report.text})}):r);
      return s;
    },()=>{delete ui.rtext[rid];});
    const copy=()=>{
      ta.focus();ta.select();
      let ok=false;
      try{ok=document.execCommand('copy');}catch(e){ok=false;}
      msg.textContent=ok?'已复制':'已全选，请按 Ctrl/⌘+C 复制';
    };
    const dirty=cur()!==run.report.text;
    return el('div',{class:'rpt'},
      el('div',{class:'rmeta'},shortDate(run.range.start)+'–'+shortDate(run.range.end)+' · '+(run.report.reviewed?'已审阅':'待审阅')+' · 未发送'),
      el('div',{class:'note'},'仅供你审阅：卡片不会自动发送周报（平台也没有发信接口），确认后请自行复制发送。'+(st.requirements?'写作要求已保存，但平台暂无 AI 接口，草稿未据此改写。':'')),
      ta,
      errLine(),
      el('div',{class:'row wrap'},...kids([
        btn(dirty?'保存修改':'已保存',()=>saveRep(run.report.reviewed),'sec',!dirty),
        btn('复制',copy,'sec'),
        btn(run.report.reviewed?'取消已审阅':'标记已审阅',()=>saveRep(!run.report.reviewed),'primary'),
        btn('步骤结果',()=>go('run',{rid:rid,back:'report'}),'ghost'),
        msg])));
  }

  render();
}

